using System;

class PointC { public int X; }          // class: reference type
struct PointS { public int X; }         // struct: value type

class Program
{
    static void Main()
    {
        PointC c1 = new PointC { X = 1 };
        PointC c2 = c1;                  // copies the reference, same object
        c2.X = 99;
        Console.WriteLine("class : c1.X=" + c1.X + " c2.X=" + c2.X);

        PointS s1 = new PointS { X = 1 };
        PointS s2 = s1;                  // copies the whole value
        s2.X = 99;
        Console.WriteLine("struct: s1.X=" + s1.X + " s2.X=" + s2.X);

        PointC nc = null;                // default of a class is null
        PointS ds = default(PointS);     // default of a struct is all zero
        Console.WriteLine("default class null? " + (nc == null) + ", default struct X=" + ds.X);

        PointS[] arr = new PointS[3];    // one block of memory, no per-item objects
        Console.WriteLine("array of structs length=" + arr.Length + ", arr[2].X=" + arr[2].X);
    }
}

using System;
using System.Collections.Generic;

struct Counter
{
    public int N;
    public void Increment() { N++; }
}

class Program
{
    static void Main()
    {
        var list = new List<Counter> { new Counter() };
        list[0].Increment();             // indexer returns a COPY, so the list is unchanged
        Console.WriteLine("List after list[0].Increment(): " + list[0].N);

        Counter[] arr = { new Counter() };
        arr[0].Increment();              // array element is a variable, mutated in place
        Console.WriteLine("Array after arr[0].Increment(): " + arr[0].N);

        foreach (var c in list) { var copy = c; copy.Increment(); }
        Console.WriteLine("After foreach on copy: " + list[0].N);

        Counter tmp = list[0];           // the fix: modify a local, then store it back
        tmp.Increment();
        list[0] = tmp;
        Console.WriteLine("After store-back fix: " + list[0].N);
    }
}

using System;

class Logger { public string Name = "log"; }

// C# 7 equivalent of: class OrderService(Logger log, int limit)
class OrderService
{
    private readonly Logger _log;        // hidden field the compiler would create
    private int _limit;
    public int LimitCopy { get; }        // property initialised from the parameter: a SECOND copy

    public OrderService(Logger log, int limit)
    {
        _log = log;
        _limit = limit;
        LimitCopy = limit;
    }

    public void RaiseLimit() { _limit += 10; }   // mutates captured state, like a mutable parameter
    public void Show() { Console.WriteLine(_log.Name + ": captured=" + _limit + " property=" + LimitCopy); }
}

class Program
{
    static void Main()
    {
        var svc = new OrderService(new Logger(), 5);
        svc.Show();
        svc.RaiseLimit();                // captured copy changes, property copy does not
        svc.Show();
        Console.WriteLine("Two copies of one parameter drifted apart (compiler warning CS9124).");
    }
}

using System;

class Account
{
    public decimal BalanceField;                 // public field: no control
    private decimal _balance;
    public decimal Balance                       // property: can validate and change later
    {
        get { return _balance; }
        private set
        {
            if (value < 0) throw new ArgumentException("negative balance");
            _balance = value;
        }
    }
    public decimal Fee { get { return Balance * 0.01m; } }   // computed, no storage

    public void Deposit(decimal amount) { Balance += amount; }
    public void Withdraw(decimal amount) { Balance -= amount; }
}

class Program
{
    static void Main()
    {
        var a = new Account();
        a.BalanceField = -500;                   // field accepts nonsense
        Console.WriteLine("field accepted: " + a.BalanceField);

        a.Deposit(200);
        Console.WriteLine("balance=" + a.Balance + " fee=" + a.Fee);
        try { a.Withdraw(500); }
        catch (ArgumentException e) { Console.WriteLine("property rejected: " + e.Message); }
        Console.WriteLine("balance still=" + a.Balance);
    }
}

using System;

class P
{
    public int Id { get; }                       // get-only: constructor only
    public decimal Balance { get; private set; } // private set: any time, inside the class

    public P(int id) { Id = id; }                // allowed here
    public void Deposit(decimal x) { Balance += x; }
    // 'init' (C# 9) would allow: new P { X = 1 } at creation time only.
}

class Program
{
    static void Main()
    {
        var p = new P(7);
        Console.WriteLine("Id=" + p.Id + " Balance=" + p.Balance);
        p.Deposit(50);
        p.Deposit(25);                           // private set changes the object repeatedly
        Console.WriteLine("after two deposits Balance=" + p.Balance);
        // p.Id = 8;          compile error: get-only
        // p.Balance = 1;     compile error: setter is private
        Console.WriteLine("Id is fixed at " + p.Id + "; Balance is mutable only through methods.");
    }
}

using System;
using System.Collections.Generic;

// Hand-written value equality: what a record generates for you.
class PersonV
{
    public string Name { get; }
    public int Age { get; }
    public List<string> Tags { get; }
    public PersonV(string n, int a, List<string> t) { Name = n; Age = a; Tags = t; }
    public override bool Equals(object o)
    {
        var p = o as PersonV;
        return p != null && p.Name == Name && p.Age == Age && p.Tags == Tags; // list: reference compare
    }
    public override int GetHashCode() { return HashCode(Name, Age); }
    static int HashCode(string n, int a) { return n.GetHashCode() * 31 + a; }
    public override string ToString() { return "PersonV { Name = " + Name + ", Age = " + Age + " }"; }
    public PersonV With(int age) { return new PersonV(Name, age, Tags); }  // like 'with'
}

class Program
{
    static void Main()
    {
        var tags = new List<string> { "a" };
        var p1 = new PersonV("Ann", 30, tags);
        var p2 = new PersonV("Ann", 30, tags);
        var p3 = new PersonV("Ann", 30, new List<string> { "a" });
        Console.WriteLine(p1 + " equals same-list copy: " + p1.Equals(p2));
        Console.WriteLine("equals copy with an equal-but-different list: " + p1.Equals(p3));
        Console.WriteLine("with Age=40: " + p1.With(40));
        Console.WriteLine("Collections compare by reference unless you compare contents yourself.");
    }
}

using System;
using System.Collections.Generic;

class BadKey
{
    public int Id;
    public override bool Equals(object o) { var b = o as BadKey; return b != null && b.Id == Id; }
    // BUG: no GetHashCode override, so equal objects get different hashes
}
class GoodKey
{
    public int Id;
    public override bool Equals(object o) { var g = o as GoodKey; return g != null && g.Id == Id; }
    public override int GetHashCode() { return Id.GetHashCode(); }
}
class MutKey
{
    public int Id;
    public override bool Equals(object o) { var m = o as MutKey; return m != null && m.Id == Id; }
    public override int GetHashCode() { return Id; }
}

class Program
{
    static void Main()
    {
        var bad = new HashSet<BadKey> { new BadKey { Id = 1 } };
        Console.WriteLine("BadKey  contains equal key? " + bad.Contains(new BadKey { Id = 1 }));
        var good = new HashSet<GoodKey> { new GoodKey { Id = 1 } };
        Console.WriteLine("GoodKey contains equal key? " + good.Contains(new GoodKey { Id = 1 }));

        var k = new MutKey { Id = 1 };
        var set = new HashSet<MutKey> { k };
        k.Id = 2;                                 // hash changes after insertion
        Console.WriteLine("MutKey after mutation, Contains(k)? " + set.Contains(k));
        k.Id = 1;
        Console.WriteLine("MutKey after restoring,  Contains(k)? " + set.Contains(k));
    }
}

using System;

class Program
{
    class Box { public int V; }
    class Val { public int V; public override bool Equals(object o) { var x = o as Val; return x != null && x.V == V; }
                public override int GetHashCode() { return V; } }

    static void Main()
    {
        object a = "hi";
        object b = new string(new[] { 'h', 'i' });
        Console.WriteLine("object a==b           : " + (a == b));           // reference ==
        Console.WriteLine("a.Equals(b)           : " + a.Equals(b));         // string value Equals
        Console.WriteLine("ReferenceEquals(a,b)  : " + ReferenceEquals(a, b));
        string s1 = "hi", s2 = new string(new[] { 'h', 'i' });
        Console.WriteLine("string s1==s2         : " + (s1 == s2));          // string overloads ==

        var b1 = new Box { V = 1 }; var b2 = new Box { V = 1 };
        Console.WriteLine("Box Equals / ==       : " + b1.Equals(b2) + " / " + (b1 == b2));
        var v1 = new Val { V = 1 }; var v2 = new Val { V = 1 };
        Console.WriteLine("Val Equals / ==       : " + v1.Equals(v2) + " / " + (v1 == v2));
        Console.WriteLine("(object)v1 == v2      : " + ((object)v1 == (object)v2));
    }
}

using System;

struct Big
{
    public int N;
    public void Bump() { N++; }                       // mutating member
    public int Read() { return N; }
}

class Holder
{
    public readonly Big Item = new Big();             // readonly field of a mutable struct
}

class Program
{
    static void Main()
    {
        var h = new Holder();
        h.Item.Bump();                                // compiler calls Bump on a hidden COPY
        Console.WriteLine("readonly field after Bump(): " + h.Item.N);   // still 0

        Big local = new Big();
        local.Bump();                                 // a normal variable is mutated in place
        Console.WriteLine("local after Bump(): " + local.N);

        // A 'readonly struct' (C# 7.2) promises no mutation, so the compiler can skip the copy.
        // Here we show the safe pattern by hand: do not mutate, create a new value.
        Big next = h.Item;
        next.Bump();
        Console.WriteLine("explicit copy then Bump: " + next.N + ", original " + h.Item.N);
    }
}

using System;
using System.Threading;

interface IClock { DateTime Now(); }
class SystemClock : IClock { public DateTime Now() { return DateTime.UtcNow; } }
class FixedClock : IClock { public DateTime Now() { return new DateTime(2020, 1, 1); } }

class Singleton
{
    static int created = 0;
    // Lazy<T> creates the instance once, thread-safely, on first use
    static readonly Lazy<Singleton> instance = new Lazy<Singleton>(() => new Singleton());
    Singleton() { Interlocked.Increment(ref created); }
    public static Singleton Instance { get { return instance.Value; } }
    public static int Created { get { return created; } }
}

class Program
{
    static string Describe(IClock clock) { return "year " + clock.Now().Year; }

    static void Main()
    {
        Console.WriteLine("created before use: " + Singleton.Created);
        var a = Singleton.Instance;
        var b = Singleton.Instance;
        Console.WriteLine("same instance: " + ReferenceEquals(a, b) + ", created: " + Singleton.Created);
        // Injected dependency: tests can pass a fake, a static class cannot be replaced
        Console.WriteLine("fixed clock: " + Describe(new FixedClock()));
    }
}

using System;

struct Money
{
    public readonly decimal Amount;
    public readonly string Currency;
    public Money(decimal amount, string currency)
    {
        if (string.IsNullOrEmpty(currency) || currency.Length != 3) throw new ArgumentException("bad currency");
        Amount = amount; Currency = currency;
    }
    public Money Add(Money o)
    {
        if (o.Currency != Currency) throw new InvalidOperationException("currency mismatch");
        return new Money(Amount + o.Amount, Currency);   // new value, original untouched
    }
    public Money[] Split(int parts)                      // allocate in cents so the sum is exact
    {
        long cents = (long)(Amount * 100), each = cents / parts, rest = cents % parts;
        var r = new Money[parts];
        for (int i = 0; i < parts; i++) r[i] = new Money((each + (i < rest ? 1 : 0)) / 100m, Currency);
        return r;
    }
    public override string ToString() { return Amount.ToString("0.00") + " " + Currency; }
}

class Program
{
    static void Main()
    {
        var a = new Money(10.10m, "USD");
        var b = new Money(5.25m, "USD");
        Console.WriteLine(a + " + " + b + " = " + a.Add(b));
        foreach (var m in new Money(100.00m, "USD").Split(3)) Console.Write(m + "; ");
        Console.WriteLine();
        Console.WriteLine("0.1+0.2==0.3 as double: " + (0.1 + 0.2 == 0.3) + ", as decimal: " + (0.1m + 0.2m == 0.3m));
        try { a.Add(new Money(1m, "EUR")); }
        catch (InvalidOperationException e) { Console.WriteLine("rejected: " + e.Message); }
    }
}

using System;

class Person
{
    public string Name;
    public int Age;
    public string[] Tags;

    protected Person(Person original)            // like the record's copy constructor
    { Name = original.Name; Age = original.Age; Tags = original.Tags; }
    public Person(string n, int a, string[] t) { Name = n; Age = a; Tags = t; }
    public virtual Person Clone() { return new Person(this); }  // like <Clone>$()
    public override string ToString() { return Name + " " + Age + " tags=" + string.Join(",", Tags); }
}

class Program
{
    static void Main()
    {
        var p1 = new Person("Ann", 30, new[] { "x" });
        // var p2 = p1 with { Age = 40 };  is roughly:
        Person p2 = p1.Clone();   // 1. copy all fields (shallow)
        p2.Age = 40;              // 2. then assign the braces members
        Console.WriteLine("p1: " + p1);
        Console.WriteLine("p2: " + p2);
        Console.WriteLine("Tags array shared (shallow copy): " + ReferenceEquals(p1.Tags, p2.Tags));
        p2.Tags[0] = "changed";
        Console.WriteLine("p1 tags now: " + string.Join(",", p1.Tags));
    }
}

using System;

class Range
{
    public int Start { get; private set; }
    public int End { get; private set; }
    public Range(int start, int end)              // constructor enforces the invariant
    {
        if (start > end) throw new ArgumentException("Start must be <= End");
        Start = start; End = end;
    }
}

class LooseRange                                  // initializer style: no invariant possible
{
    public int Start { get; set; }
    public int End { get; set; }
}

class Program
{
    static void Main()
    {
        var bad = new LooseRange { Start = 10, End = 1 };   // compiles and "works"
        Console.WriteLine("LooseRange accepted Start=" + bad.Start + " End=" + bad.End);
        try { var r = new Range(10, 1); Console.WriteLine(r.Start); }
        catch (ArgumentException e) { Console.WriteLine("Range refused: " + e.Message); }
        var ok = new Range(1, 10);
        Console.WriteLine("Range ok: " + ok.Start + ".." + ok.End);
    }
}
